using System.IO;using GymOS.Windows;using Microsoft.Data.Sqlite;
var folder=Path.Combine(Path.GetTempPath(),"gymos-smoke-"+Guid.NewGuid());Directory.CreateDirectory(folder);var file=Path.Combine(folder,"backups.sqlite");
try{BackupStore.Save(file,"tenant-a","{\"private\":\"one\"}");BackupStore.Save(file,"tenant-b","{\"private\":\"two\"}");BackupStore.Save(file,"tenant-a","{\"private\":\"latest\"}");if(BackupStore.Latest(file,"tenant-a")!="{\"private\":\"latest\"}"||BackupStore.Latest(file,"tenant-b")!="{\"private\":\"two\"}")throw new Exception("Tenant/latest mismatch");bool rejected=false;try{BackupStore.Latest(file,"missing");}catch(InvalidOperationException){rejected=true;}if(!rejected)throw new Exception("Missing tenant not rejected");using(var c=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=file}.ToString())){c.Open();using var cmd=c.CreateCommand();cmd.CommandText="SELECT payload FROM snapshots LIMIT 1";var blob=(byte[])cmd.ExecuteScalar()!;if(System.Text.Encoding.UTF8.GetString(blob).Contains("private"))throw new Exception("Plaintext payload");cmd.CommandText="select sqlite_version()";Console.WriteLine("SQLite "+cmd.ExecuteScalar());}Console.WriteLine("PASS: encrypted SQLite snapshots, latest selection, tenant isolation and missing-tenant rejection");}finally{SqliteConnection.ClearAllPools();File.Delete(file);Directory.Delete(folder);}
foreach(var action in new[]{"status","chooseDatabase","save","export","refreshSignIn","speechSettings"})if(!DesktopCommands.Allowed(action))throw new Exception("Missing desktop action");foreach(var action in new[]{"run","openPath","powershell","https://evil.example"})if(DesktopCommands.Allowed(action))throw new Exception("Unexpected desktop action");Console.WriteLine("PASS: desktop command allowlist");

var trialFolder=Path.Combine(Path.GetTempPath(),"gymos-trial-test-"+Guid.NewGuid());try{var now=DateTimeOffset.UtcNow;var clock=new LocalTrialClock(trialFolder);var first=clock.Activate(now,now.AddDays(30),now);if(!clock.Allowed(now.AddDays(29)))throw new Exception("Trial closed early");var reopened=new LocalTrialClock(trialFolder);var receipt=reopened.Activate(now.AddDays(29),now.AddDays(59),now.AddDays(29));if(receipt.Ends!=first.Ends||reopened.Allowed(now.AddDays(30)))throw new Exception("Trial reset or failed to expire");if(reopened.Allowed(now))throw new Exception("Clock rollback accepted");Console.WriteLine("PASS: local encrypted 30-day timer survives reopen, never extends, rejects expiry and clock rollback");}finally{if(Directory.Exists(trialFolder))Directory.Delete(trialFolder,true);}
